export const levels=['Low','Moderate','Severe','Critical'];
export const percentages=[12,34,68,89];
export const statuses=['Grid conditions currently appear stable.','Grid pressure is rising. A little preparation now can help.','Grid conditions are deteriorating. Prepare essential backup power.','Outage risk is critical. Prepare for possible imminent power loss.'];
const actions={household:[['No urgent action needed','Keep devices normally charged'],['Consider charging phone and laptop','Charge power bank','Save important work'],['Charge essential devices now','Prepare backup lighting','Save computer work','Minimise opening refrigerator/freezer'],['Prepare for imminent outage','Fully charge essential devices','Ensure power banks are ready','Prepare backup lighting','Protect refrigerated essentials','Save all important work immediately']],medical:[['Ensure backup battery is available'],['Begin charging backup battery','Check backup power source'],['Fully charge medical equipment backup','Confirm alternative power source','Notify caregiver/support person if needed'],['Prepare for possible imminent power loss','Switch or prepare backup power immediately','Confirm remaining battery duration','Contact caregiver/support if backup time may be insufficient']]};
const offsets={A:0,B:1,C:0,D:1,E:0,F:1,G:2,H:0,I:1,J:0,K:1,L:0,M:1,N:0,O:0,P:1,R:1,S:0,T:0,U:1,V:2,W:0,X:0,Y:0,Z:0};
// Replace this provider with the ML service when available. No live data is requested.
export const demoProvider={prediction(step,profile){return {level:levels[step],percentage:percentages[step],status:statuses[step],actions:actions[profile][step],stability:['Stable','Fluctuating','Unstable','Highly unstable'][step],demand:['Normal','Elevated','High','Peak load'][step]};},regionStep(code,step){const offset=offsets[code?.replace('VE-','')];return offset===undefined?null:Math.min(3,step+offset);}};
